                clases: "Paladín",
                informacion: "Invocas un espíritu que asume la forma de un corcel especialmente inteligente, fuerte y leal, creando un vínculo duradero con él. Aparece en un espacio libre dentro del alcance y toma una forma de tu elección entre las siguientes: un caballo de batalla, un poni, un camello, un alce o un mastín (tu DM puede permitir que otros animales sean invocados como corceles). Aparece en un espacio libre dentro del alcance y tiene el perfil de la forma elegida, aunque su tipo es celestial, feérico o infernal (a tu elección) en vez de bestia. Además, si tu corcel tiene Inteligencia 5 o menos, esta pasa a ser 6 y podrá entender un idioma de tu elección que hables.*El corcel te sirve como montura, tanto dentro como fuera del combate, y tenéis un vínculo instintivo que os permite luchar como si fuerais uno. Mientras estés cabalgando sobre él, puedes elegir que cualquier conjuro que lances que te afecte solo a ti afecte también a tu corcel.*Si sus puntos de golpe se reducen a 0, desaparece sin dejar rastro físico alguno. Puedes desconvocarlo en cualquier momento como acción, haciendo que desaparezca.*Sea cual sea el caso, lanzar este conjuro de nuevo invoca al mismo corcel, devolviéndole a sus puntos de golpe máximos.*Mientras tu corcel esté a 1 milla de ti, puedes comunicarte con él telepáticamente.*No puedes estar atado mediante este conjuro a más de un corcel a la vez."
