                informacion: "Radias una energía divina, distorsionando y diseminando la energía mágica en una esfera de 30 pies a tu alrededor. La esfera se mueve contigo, centrada en ti, hasta el final del conjuro. Hasta ese momento, cada criatura amistosa en el área (incluido tú) tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos. Además, una criatura afectada no recibirá ningún daño si tiene éxito en una tirada de salvación contra un conjuro o efecto mágico que permite hacer una tirada de salvación para recibir solo la mitad del daño."
