                informacion: "Una ola de curación emana desde un punto de tu elección dentro del alcance. Elige hasta 6 criaturas dentro de una esfera de 30 pies centrada en ese punto. Cada una recupera tantos puntos de golpe como 3d8 + tu modificador por aptitud mágica. Este conjuro no afecta a muertos vivientes o autómatas.*A niveles superiores. Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 6 o más, la curación aumenta en 1d8 por cada nivel por encima de 5 que tenga el espacio que hayas empleado."
