                ataque: "Ninguno",
                clases: "Druida, Hechicero y Mago",
                informacion: "Un muro no mágico de piedra sólida surge en un punto de tu elección dentro del alcance. Este tiene 6 pulgadas de grosor y está formado por diez paneles cuadrados de 10 por 10 pies. Cada panel debe ser contiguo a otro. De forma alternativa, puedes crear paneles rectangulares de 10 pies por 20 pies, pero solo tendrán 3 pulgadas de grosor.*Si el muro atraviesa el espacio de una criatura cuando aparece, esta se verá empujada a uno u otro lado del muro (a tu elección). Si una criatura fuera a quedar completamente rodeada por el muro (o por el muro y otra superficie sólida), esta puede hacer una tirada de salvación de Destreza. Si tiene éxito, puede usar su reacción para mover hasta su velocidad de manera que no quede encerrada por el muro.*El muro puede tener cualquier forma que desees, pero no puede ocupar el mismo espacio que una criatura u objeto. No es necesario que sea vertical o que descanse sobre unos cimientos sólidos. Sin embargo, sí que es obligatorio que se funda con un cuerpo de piedra existente, y que este pueda sostener el muro. De esta manera, podrías usar el conjuro para salvar un abismo o crear una rampa.*Si creas una arcada de más de 20 pies de longitud, debes reducir a la mitad el tamaño de cada panel para crear estructuras de soporte. Además, eres capaz, de manera tosca, de dar forma al muro para añadir almenas, parapetos, etc.*El muro es un objeto hecho de piedra que puede ser dañado y por tanto atravesado. Cada panel tiene CA 15 y 30 puntos de golpe por cada pulgada de grosor. Reducir a un panel a 0 puntos de golpe lo destruye, y podría, a discreción del DM, hacer que otros paneles conectados se derrumbasen.*Si mantienes tu concentración en el conjuro durante toda su duración, el muro se convierte en permanente y no puede ser disipado. En caso contrario, el muro desaparece cuando el conjuro termina."
