                tiradaDeSalvacion: "Destreza mitad",
                ataque: "Contra salvación 7d8 perforante",
                clases: "Druida",
                informacion: "Creas un muro de maleza resistente, flexible y enmarañada, cuajada de espinas afiladas como agujas. Este aparece sobre una superficie sólida dentro del alcance y permanece hasta el final de la duración del conjuro. Puedes crear un muro recto de hasta 60 pies de largo, 10 de alto y 5 de ancho o un muro en forma de anillo de 20 pies de diámetro, hasta 20 pies de alto y 5 de grosor. En cualquier caso, bloquea la línea de visión.*Cuando el muro aparece, todas las criaturas en la zona deben hacer una tirada de salvación de Destreza. Sufrirán 7d8 de daño perforante si fallan la tirada o la mitad del daño si la superan.*Una criatura puede atravesar el muro, pero será una tarea lenta y dolorosa. Deberá emplear 4 pies de movimiento por cada pie que quiera mover. Además, cuando una criatura entra en el área del muro por primera vez en un turno, o cuando empieza su turno en ella, debe realizar una tirada de salvación de Destreza. Sufrirá 7d8 de daño cortante si falla la tirada o la mitad del daño si la supera.*A niveles superiores. Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 7 o más, el daño aumenta en 1d8 por cada nivel por encima de 6 del espacio."
