                alcance: "120 pies",
                duracion: "Concentración, hasta 10 minutos",
                ataque: "Contra salvación 10d6 frío",
                clases: "Mago",
                informacion: "Creas un muro de hielo en una superficie sólida que puedas ver dentro del alcance. Puedes darle forma de cúpula semiesférica o de esfera con un radio de hasta 10 pies, o puedes crear una superficie plana compuesta por diez paneles de 10 por 10 pies. Cada panel debe ser contiguo a otro. En cualquiera de las formas, el muro tiene 1 pie de ancho y dura hasta el final del conjuro.*Si el muro atraviesa el espacio de una criatura al aparecer, esta será empujada a un lado del muro y deberá hacer una tirada de salvación de Destreza. La criatura sufrirá 10d6 de daño de frío si falla la tirada o la mitad del daño si la supera.*El muro es un objeto que puede ser dañado y por tanto atravesado. Tiene CA 12 y 30 puntos de golpe por cada sección de 10 pies, además de ser vulnerable al daño de fuego. Reducir una sección de 10 pies del muro a 0 puntos de golpe la destruye y deja una capa de aire helado en el espacio que ocupaba el muro. Cuando una criatura atraviesa esta capa de aire por primera vez en un turno, debe realizar una tirada de salvación de Constitución. Sufrirá 5d6 de daño de frío si falla la tirada o la mitad del daño si la supera.*A niveles superiores. Cuando lanzas este conjuro utilizando un espacio de conjuro de nivel 7 o más, el daño que inflige el muro al aparecer aumenta en 2d6, y el daño por atravesar la capa de aire helado aumenta en 1d6 por cada nivel por encima de 6 del espacio."
