                tiempoDeLanzamiento: "1 acción",
                alcance: "Lanzador (esfera de 10 pies de radio)",
                duracion: "Concentración, hasta 1 hora",
                ataque: "--",
                clases: "Clérigo y Mago",
                informacion: "Te rodea una esfera antimagia invisible de 10 pies de radio. El área cubierta queda aislada de la energía mágica que permea el universo. Dentro de la esfera no se pueden lanzar conjuros, las criaturas invocadas desaparecen y los objetos mágicos se vuelven mundanos. La esfera se mueve contigo, centrada en ti, hasta el final del conjuro.*Los conjuros y otros efectos mágicos, exceptuando aquellos creados por un artefacto o una deidad, no pueden penetrar en la esfera y quedan suprimidos dentro de ella. Los espacios de conjuro empleados en lanzar conjuros que queden suprimidos se gastan con normalidad. Mientras un conjuro está suprimido, no tiene efecto, pero el tiempo que pasa en este estado se resta de su duración normal.*Efectos que eligen un objetivo. Los conjuros y efectos mágicos que eligen como objetivo a una criatura u objeto, como proyectil mágico o hechizar persona, no tienen efecto si su objetivo está dentro de la esfera.*Áreas de efecto mágico. El área de otro conjuro o efecto mágico, como una bola de fuego, no se extiende al interior de la esfera. Si la esfera se superpone con el área de un efecto mágico, este queda anulado en la parte de área cubierta por la esfera. Por ejemplo, las llamas creadas por un muro de fuego quedan suprimidas dentro de la esfera. Si el área superpuesta es lo suficientemente grande, se crea un hueco en el muro.*Conjuros. Cualquier conjuro o efecto mágico activo en una criatura u objeto dentro de la esfera queda suprimido mientras la criatura o el objeto permanezca en su interior.*Objetos mágicos. Los poderes y propiedades de los objetos mágicos quedan suprimidos dentro de la esfera. Por ejemplo, una espada larga +1 se comporta dentro de la esfera como una espada larga no mágica.*Los poderes y propiedades de un arma mágica quedan suprimidos si se usan contra un objetivo dentro de la esfera o si las empuña un atacante dentro de la esfera. Si un arma mágica o una unidad de munición mágica abandona por completo la esfera (por ejemplo, una flecha mágica disparada o una lanza mágica arrojada contra un objetivo fuera de la esfera) su magia deja de quedar suprimida en el momento en que sale del campo antimagia.*Viajes mágicos. La teletransportación y el viaje interplanar no funcionan si el origen o el destino están dentro de la esfera de un campo antimagia. Un portal a otra localización, mundo o plano de existencia, así como cualquier tipo de apertura a un espacio extradimensional, como el creado por el conjuro truco de la cuerda, se cierra temporalmente mientras permanezca dentro de la esfera.*Criaturas y objetos. Una criatura o un objeto invocado o creado mediante magia deja de existir en el momento en que entre en la esfera. Reaparecerá instantáneamente en cuanto el espacio que ocupaba no se superponga con el de la esfera.*Disipar magia. Los conjuros y efectos mágicos similares a disipar magia no tienen efecto sobre la esfera. Del mismo modo, las esferas creadas por conjuros de campo antimagia diferentes no se anulan entre sí."
