                informacion: "Creas una puerta de sombras en una superficie sólida y plana que puedas ver dentro del alcance. Esta puerta es suficientemente grande para permitir el paso sin trabas de criaturas Medianas. Cuando está abierta, la puerta lleva a un semiplano que parece una habitación vacía de 30 pies de lado en cada dimensión, hecha de madera o de piedra. Cuando el conjuro termina, la puerta desaparece y cualquier criatura u objeto dentro del semiplano permanece encerrado en él, al desaparecer la puerta en ambos lados.*Cada vez que lanzas este conjuro eres capaz de crear un semiplano nuevo o hacer que la puerta de sombras conecte con un plano que creaste en un lanzamiento anterior de este conjuro. Además, si conoces la naturaleza y contenidos de un semiplano creado mediante este conjuro por otra criatura, puedes hacer que la puerta de sombras conecte con ese semiplano."
