                informacion: "Creas un fenómeno sísmico en un punto del suelo que puedas ver dentro del alcance. Hasta el final de la duración del conjuro, un intenso temblor arrasa el área en un radio de 100 pies alrededor del punto, haciendo temblar a las criaturas y estructuras en la zona y en contacto con el suelo.*El terreno en el área pasa a considerarse difícil. Todas las criaturas sobre él que estén concentrándose deberán hacer una tirada de salvación de Constitución. Si fallan, su concentración se rompe.*En el momento de lanzar el conjuro y al final de cada turno en el que sigas concentrándote en él, cada criatura sobre el suelo del área debe realizar una tirada de salvación de Destreza. Si falla, es derribada.*Este conjuro puede tener efectos adicionales dependiendo del tipo de terreno en el área, a determinar por el DM.*Grietas. Al comienzo de tu siguiente turno después del lanzamiento del conjuro se abren varias grietas en el área. Un total de 1d6 fisuras aparecen en localizaciones elegidas por el DM. Cada una de ellas es de 1d10 x 10 pies de profundidad, 10 de ancho y se extiende de un borde del área al lado opuesto. Una criatura de pie en un punto donde se abre una fisura debe tener éxito en una tirada de salvación de Destreza o caerá dentro. Si tiene éxito, se desplaza a un lado de la fisura mientras esta se abre.*Una fisura que se abra justo debajo de una estructura provoca que esta se derrumbe automáticamente (ver más abajo).*Estructuras. El temblor hace 50 de daño contundente a cualquier estructura en contacto con el suelo del área cuando lanzas el conjuro y al principio de cada uno de tus turnos hasta que este termine. Si los puntos de golpe de una estructura se reducen a 0, esta se derrumbará y puede dañar a las criaturas cercanas. Las criaturas que estén a una distancia menor o igual a la mitad de la altura de la estructura deben realizar una tirada de salvación de Destreza. Si fallan, recibirán 5d6 de daño contundente, serán derribadas y estarán enterradas entre los escombros. Es necesario superar una prueba de Fuerza (Atletismo) CD 20 para escapar. El DM puede ajustar la CD según la naturaleza de los escombros. Si la criatura supera la tirada de salvación, solo recibe la mitad del daño y no resulta derribada o enterrada."
