                informacion: "Creas un cautiverio mágico para apresar a una criatura que puedas ver dentro del alcance. El objetivo debe tener éxito en una tirada de salvación de Sabiduría o quedará atado por el conjuro; si la supera, es inmune al mismo si volvieras a lanzarlo. Mientras la criatura está afectada por este conjuro, no envejece y además no necesita comer, beber ni respirar. Los conjuros de adivinación no podrán localizarla o percibirla.*Cuando lanzas este conjuro, elige una de las siguientes formas de reclusión:*Entierro. El objetivo queda sepultado en lugar muy profundo bajo el suelo, dentro de una esfera de fuerza mágica del tamaño justo para contenerlo. Nada puede atravesar la esfera, ni ninguna criatura podrá entrar o salir de ella utilizando teletransportación o viaje interplanar.*El componente especial para esta versión del conjuro es un pequeño orbe de mithral.*Encadenamiento. Pesadas cadenas, firmemente ancladas al suelo, atan al objetivo, que está apresado hasta el final del conjuro, y no puede moverse o ser desplazado de ninguna manera hasta entonces.*El componente especial para esta versión del conjuro es una cadena fina de un metal precioso.*Presidio cercado. El conjuro transporta al objetivo a un pequeño semiplano, protegido contra la teletransportación y el viaje interplanar. El semiplano puede ser un laberinto, una jaula o cualquier estructura o zona confinada de tu elección.*El componente especial de esta versión del conjuro es una representación en miniatura de la prisión, hecha en jade.*Contención mínima. El objetivo queda reducido a una altura de 1 pulgada y aprisionado dentro de una gema u objeto similar. La luz puede pasar a través de la gema con normalidad (permitiendo al objetivo ver el exterior y a otras criaturas ver dentro), pero nada más puede entrar o salir, ni siquiera mediante teletransportación o viaje interplanar. La gema no puede ser cortada o rota mientras el conjuro siga en efecto.*El componente especial de esta versión del conjuro es una gema grande y transparente, como un corindón, un diamante o un rubí.*Sueño. El objetivo cae dormido y no puede ser despertado. El componente especial para esta versión del conjuro es un conjunto de hierbas soporíferas poco frecuentes.*Terminar el conjuro. Durante el lanzamiento de cualquiera de las versiones del conjuro, puedes especificar una condición que finalizará el conjuro y liberará al objetivo. La condición puede ser tan específica o complicada como quieras, aunque el DM debe estar de acuerdo en que sea razonable y pueda llegar a ocurrir. Puede depender del nombre de la criatura, su identidad o deidad, pero por lo demás debe estar basada en acciones o cualidades visibles y no en magnitudes intangibles como su clase, nivel o puntos de golpe.*El conjuro disipar magia solo puede finalizar este conjuro si se lanza como uno de nivel 9, eligiendo como objetivo a la prisión o al componente especial utilizado en su creación.*Solo puedes emplear un componente especial concreto para crear una prisión a la vez. Si vuelves a lanzar el conjuro usando el mismo componente, el objetivo del primer lanzamiento queda en libertad inmediatamente."
